    padding: 0.75rem 1rem;
    background: #f9fafb;
    border-bottom: 1px solid #e5e7eb;
    border-left: 3px solid #2563eb;
    margin: 0.75rem 1rem;
    border-radius: 4px;
}

.thread-root-message .message-author {
    font-weight: 700;
    font-size: 0.85rem;
}

