    font-size: 0.85rem;
    color: #4b5563;
    margin-top: 0.25rem;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 0.5rem 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.thread-reply {
